def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive_bids = []
    for agent_id in opponents_status:
        opp = opponents_status[agent_id]
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 90:
                    aggressive_bids.append(float(bid))

    if not alive:
        return min(budget, 12.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    alive_count = len(alive) + 1

    scarcity = supply / float(WATER_REQ * alive_count)

    emergency = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    if emergency:
        bid = max(62.0, highest_prev * 0.72 + 6.0)
        if supply <= 16:
            bid += 10.0
        return min(budget, bid)

    if scarcity >= 0.42 and len(aggressive_bids) >= 2 and hp >= 7 and no_water_days == 0:
        return min(budget, 0.0)

    if supply >= 23 and hp >= 6 and no_water_days == 0:
        return min(budget, 8.0)

    if supply <= 17:
        bid = max(38.0, min(78.0, avg_prev * 0.42 + 10.0))
        if pressured:
            bid += 12.0
        return min(budget, bid)

    if pressured:
        bid = max(30.0, min(68.0, highest_prev * 0.32 + 8.0))
        return min(budget, bid)

    bid = 16.0
    if highest_prev >= 120:
        bid = 10.0
    elif highest_prev >= 80:
        bid = 12.0
    elif highest_prev > 0:
        bid = min(26.0, highest_prev * 0.25 + 4.0)

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.85

    return min(budget, max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Immediate reaction from yesterday trace bids
    prev_bids = []
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    # Estimate how aggressive the field was yesterday
    if prev_bids:
        highest_prev = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
    else:
        highest_prev = 0.0
        second_prev = 0.0

    # If Cindy-like behavior (very high bids) happened, we don't need to match it.
    # We target a bid that is likely sufficient under medium supply without burning budget.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)  # 0..1

    # Urgency increases with hp and consecutive no-water days
    urgency = 0.0
    if hp <= 2.0:
        urgency += 0.9
    elif hp <= 4.0:
        urgency += 0.6
    elif hp <= 6.0:
        urgency += 0.35
    else:
        urgency += 0.15

    if no_water_days >= 3:
        urgency += 0.6
    elif no_water_days == 2:
        urgency += 0.3
    elif no_water_days == 1:
        urgency += 0.15

    # Base bid level: medium supply => moderate bid
    base = DAILY_SALARY * (0.35 + 0.25 * supply_ratio)

    # If yesterday had extreme bids, slightly increase but cap far below their max.
    if highest_prev >= DAILY_SALARY * 1.2:
        base = max(base, DAILY_SALARY * (0.45 + 0.15 * supply_ratio))

    # If yesterday's highest was not extreme, try to beat the second-highest a bit.
    target = base + urgency * (DAILY_SALARY * 0.25)

    if highest_prev < DAILY_SALARY * 1.2 and second_prev > 0:
        target = max(target, second_prev + 2.0)

    # Never bid more than we can afford; also avoid wasting when hp is healthy.
    if hp >= 7.0 and no_water_days == 0:
        cap = DAILY_SALARY * 0.65
    elif hp >= 7.0:
        cap = DAILY_SALARY * 0.85
    else:
        cap = DAILY_SALARY * 0.95

    bid = min(budget, cap, target)

    # Safety: ensure non-negative and at least a small bid if budget allows.
    if bid < 0.0:
        bid = 0.0
    if budget > 0 and bid == 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

